import com.truckload.controller.GeoModel;
public class GeoProtocolTest {
 static int count;static void check(boolean value,String name){if(!value)throw new AssertionError(name);count++;}
 static void area(GeoModel m,String name){m.apply("GEO_LIST_BEGIN",1);m.apply("GEO_AREA|2|"+name+"|20|1|C|50|1",1);m.apply("GEO_VERTEX|2|0|0",1);m.apply("GEO_AREA_ACTION|2|DRIVING|1|11|FF0000|0000FF|140",1);m.apply("GEO_AREA_ACTION|2|STOPPED|2|0|FFFFFF|000000|255",1);}
 public static void main(String[] args){GeoModel m=new GeoModel();check(m.apply("GEO_CONFIG|1|0|2500|5|1|3|12|12",1)&&m.ready&&m.enabled,"valid config");check(!m.apply("GEO_CONFIG|0|1|2500|5|4|3|12|12",2)&&m.enabled&&!m.manualOverride,"invalid config is atomic");check(m.apply("GROUND_CONFIG|1500|350|1|0|-250|600",1)&&m.reverse[0]&&!m.reverse[1]&&m.offset[0]==-250,"independent directions and offsets");check(!m.apply("GROUND_CONFIG|100|350|0|1|0|0",1)&&m.reverse[0]&&m.spacing==1500,"invalid ground config is atomic");m.apply("GROUND_STATE|1|6.5|100",1);check(!m.apply("GROUND_STATE|0|nan|-1",2)&&m.groundFresh&&m.speed==6.5&&m.groundAt==1,"invalid speed record atomic");check(m.apply("GROUND_STATE|0|nan|100",2)&&!m.groundFresh&&Double.isNaN(m.speed),"stale speed explicit");area(m,"Scale");check(m.areas.isEmpty(),"staged list hidden");check(m.apply("GEO_LIST_END",1)&&m.areas.size()==1&&m.areas.get(0).actions[0].pattern==11,"complete area readback");area(m,"Broken");m.apply("GEO_VERTEX|2|91|0",1);check(!m.apply("GEO_LIST_END",1)&&m.areas.get(0).name.equals("Scale"),"invalid list retains previous");m.apply("GEO_LIST_BEGIN",1);m.apply("GEO_AREA|0|Missing|10|1|P|50|3",1);check(!m.apply("GEO_LIST_END",1)&&m.areas.size()==1,"incomplete list retains previous");check(!m.apply("GEO_FALLBACK|NO_FIX|0|11|FFFFFF|000000|140",1),"load effect range checked");check(m.apply("GEO_FALLBACK|NO_FIX|3|0|FFFFFF|000000|140",1)&&m.fallback[2].mode==3,"no fix action");check(m.apply("GEO_STATE|AUTO|2|Scale|DRIVING|1|11|FF0000|0000FF|140|1|0",3)&&m.active&&m.activeId==2&&m.activeAction.pattern==11,"active area state");check(!m.apply("GEO_STATE|AUTO|2|Scale|UNKNOWN|1|11|FF0000|0000FF|140|1|0",4)&&m.stateAt==3,"invalid state retains previous");GeoModel.Area copy=m.areas.get(0).copy();copy.points.get(0).lat=12;copy.actions[0].mode=3;check(m.areas.get(0).points.get(0).lat==0&&m.areas.get(0).actions[0].mode==1,"edit draft independent");check(m.freeId()==0,"available area slot");System.out.println("GeoProtocolTest PASS "+count);}
}
